<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();verify_csrf();$me=(int)$u['id'];$other=(int)($_POST['receiver_id']??0);$intent=$_POST['intent']??'';$pdo=db();if($intent==='send'){if($other===$me||$other<1){flash('danger','You cannot request yourself.');go('../student/find-partners.php');}$q=$pdo->prepare("SELECT id,status FROM study_requests WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) ORDER BY id DESC LIMIT 1");$q->execute([$me,$other,$other,$me]);$existing=$q->fetch();if($existing&&$existing['status']==='pending'){flash('warning','A request between you is already pending.');go('../student/partner-details.php?id='.$other);}if($existing&&$existing['status']==='accepted'){flash('warning','You are already connected.');go('../student/messages.php?user='.$other);}try{$pdo->prepare('INSERT INTO study_requests(sender_id,receiver_id,message,status) VALUES(?,?,?,\'pending\')')->execute([$me,$other,trim($_POST['message']??'')]);notify($other,$u['name'].' sent you a study request.','requests.php');flash('success','Study request sent.');}catch(PDOException $e){flash('warning','A request already exists for this connection.');}go('../student/find-partners.php');} $rid=(int)($_POST['request_id']??0);$q=$pdo->prepare('SELECT * FROM study_requests WHERE id=?');$q->execute([$rid]);$r=$q->fetch();if(!$r){flash('danger','Request not found.');go('../student/requests.php');}if($intent==='cancel'&&$r['sender_id']==$me&&$r['status']==='pending'){$pdo->prepare("UPDATE study_requests SET status='cancelled' WHERE id=?")->execute([$rid]);flash('success','Request cancelled.');}elseif(in_array($intent,['accept','reject'],true)&&$r['receiver_id']==$me&&$r['status']==='pending'){$status=$intent==='accept'?'accepted':'rejected';$pdo->prepare('UPDATE study_requests SET status=? WHERE id=?')->execute([$status,$rid]);notify((int)$r['sender_id'],$u['name'].' '.$status.' your study request.','requests.php');flash('success','Request '.$status.'.');}else flash('danger','That action is not available.');go('../student/requests.php');
